const insuredItemFor = (damage: Damage, items: Item[]): Item =>
  items.find((item) => item.type === damage.itemType)!;

// Each damaged item carries its own deductible, and a damage smaller than the
// deductible contributes nothing rather than clawing money back off the claim.
const payoutForDamage = (damage: Damage, items: Item[]): number => {
  const item = insuredItemFor(damage, items);
  const reimbursed = reimbursedAmount(item, damage.amount);

  return Math.max(0, reimbursed - DEDUCTIBLE_PER_DAMAGE);
};

const payoutForIncident = (incident: Incident, items: Item[]): number =>
  incident.damages.reduce(
    (total, damage) => total + payoutForDamage(damage, items),
    0,
  );
